package com.drs.compute.model;

import java.io.Serializable;
import java.util.*;

/**
 * Output data model for MapReduce rescue task analytics (Exp 7).
 * Corresponds to the schema generated by Apache Spark and the Java Streams fallback.
 */
public class AnalyticsResult implements Serializable {
    private static final long serialVersionUID = 1L;

    private String appName;
    private String timestamp;
    private String inputFile;
    private int totalTasks;
    private double totalWorkload;
    private Map<String, Integer> countsPerCluster = new LinkedHashMap<>();
    private Map<String, Double> workloadPerCluster = new LinkedHashMap<>();
    private Map<String, Integer> countsPerType = new LinkedHashMap<>();
    private Map<String, Double> workloadPerType = new LinkedHashMap<>();
    private List<AnalyticsBreakdownItem> breakdown = new ArrayList<>();

    // Execution metadata for Web Dashboard
    private String engine;          // "spark", "streams", or "streams-fallback"
    private long durationMs;
    private boolean fallbackUsed;
    private List<String> steps = new ArrayList<>();

    public AnalyticsResult() {
    }

    public AnalyticsResult(String appName, String timestamp, String inputFile,
                           int totalTasks, double totalWorkload,
                           Map<String, Integer> countsPerCluster,
                           Map<String, Double> workloadPerCluster,
                           Map<String, Integer> countsPerType,
                           Map<String, Double> workloadPerType,
                           List<AnalyticsBreakdownItem> breakdown,
                           String engine, long durationMs, boolean fallbackUsed,
                           List<String> steps) {
        this.appName = appName;
        this.timestamp = timestamp;
        this.inputFile = inputFile;
        this.totalTasks = totalTasks;
        this.totalWorkload = totalWorkload;
        if (countsPerCluster != null) this.countsPerCluster = countsPerCluster;
        if (workloadPerCluster != null) this.workloadPerCluster = workloadPerCluster;
        if (countsPerType != null) this.countsPerType = countsPerType;
        if (workloadPerType != null) this.workloadPerType = workloadPerType;
        if (breakdown != null) this.breakdown = breakdown;
        this.engine = engine;
        this.durationMs = durationMs;
        this.fallbackUsed = fallbackUsed;
        if (steps != null) this.steps = steps;
    }

    public String getAppName() {
        return appName;
    }

    public void setAppName(String appName) {
        this.appName = appName;
    }

    public String getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(String timestamp) {
        this.timestamp = timestamp;
    }

    public String getInputFile() {
        return inputFile;
    }

    public void setInputFile(String inputFile) {
        this.inputFile = inputFile;
    }

    public int getTotalTasks() {
        return totalTasks;
    }

    public void setTotalTasks(int totalTasks) {
        this.totalTasks = totalTasks;
    }

    public double getTotalWorkload() {
        return totalWorkload;
    }

    public void setTotalWorkload(double totalWorkload) {
        this.totalWorkload = totalWorkload;
    }

    public Map<String, Integer> getCountsPerCluster() {
        return countsPerCluster;
    }

    public void setCountsPerCluster(Map<String, Integer> countsPerCluster) {
        this.countsPerCluster = countsPerCluster;
    }

    public Map<String, Double> getWorkloadPerCluster() {
        return workloadPerCluster;
    }

    public void setWorkloadPerCluster(Map<String, Double> workloadPerCluster) {
        this.workloadPerCluster = workloadPerCluster;
    }

    public Map<String, Integer> getCountsPerType() {
        return countsPerType;
    }

    public void setCountsPerType(Map<String, Integer> countsPerType) {
        this.countsPerType = countsPerType;
    }

    public Map<String, Double> getWorkloadPerType() {
        return workloadPerType;
    }

    public void setWorkloadPerType(Map<String, Double> workloadPerType) {
        this.workloadPerType = workloadPerType;
    }

    public List<AnalyticsBreakdownItem> getBreakdown() {
        return breakdown;
    }

    public void setBreakdown(List<AnalyticsBreakdownItem> breakdown) {
        this.breakdown = breakdown;
    }

    public String getEngine() {
        return engine;
    }

    public void setEngine(String engine) {
        this.engine = engine;
    }

    public long getDurationMs() {
        return durationMs;
    }

    public void setDurationMs(long durationMs) {
        this.durationMs = durationMs;
    }

    public boolean isFallbackUsed() {
        return fallbackUsed;
    }

    public void setFallbackUsed(boolean fallbackUsed) {
        this.fallbackUsed = fallbackUsed;
    }

    public List<String> getSteps() {
        return steps;
    }

    public void setSteps(List<String> steps) {
        this.steps = steps;
    }
}

